sys_script.script:
(function executeRule(current, previous) {
    var moved = 0;
    var errors = [];
    var assetCsv = String(current.assets_csv || '');
    var ids = assetCsv.split(',');
    var mode = String(current.mode || 'case');
    var targetCase = String(current.target_case || '');
    var targetUser = String(current.target_user || '');

    if (mode === 'case' && !targetCase) errors.push('Missing target case');
    if (mode === 'user' && !targetUser) errors.push('Missing target user');

    if (errors.length === 0) {
        for (var i = 0; i < ids.length; i++) {
            var aid = (ids[i] + '').replace(/^\s+|\s+$/g, '');
            if (!aid) continue;
            var gr = new GlideRecord('alm_asset');
            if (gr.get(aid)) {
                if (mode === 'case') {
                    gr.parent = targetCase;
                } else {
                    gr.assigned_to = targetUser;
                }
                if (gr.update()) {
                    moved++;
                } else {
                    errors.push('Update failed for ' + aid + ': ' + gr.getLastErrorMessage());
                }
            } else {
                errors.push('Asset not found: ' + aid);
            }
        }
    }

    current.asset_count = moved;
    current.processed_at = new GlideDateTime();
    if (errors.length === 0) {
        current.status = 'done';
    } else if (moved > 0) {
        current.status = 'partial';
    } else {
        current.status = 'error';
    }
    if (errors.length) {
        current.error_message = errors.join('\n');
    }
})(current, previous);
